rmSwitchOverSubFactor = MibScalar((1, 3, 6, 1, 4, 1, 9, 10, 10, 1, 1, 1), Integer32().subtype(subtypeSpec=ValueRangeConstraint(1, 32)).clone(4)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: rmSwitchOverSubFactor.setStatus('current')
if mibBuilder.loadTexts: rmSwitchOverSubFactor.setDescription('The Over Subscription Factor (OSF) is used on switch startup/OIR\n             to determine the maximum sizes of VBR-NRT and ABR/UBR queues.\n             In general, the larger the value of OSF specified, the\n             larger the queues are made at startup.\n             Denoting the maximum sizes of CBR,VBR-RT, VBR-NRT, and ABR/UBR\n             output queues for a physical interface as L1, L2, L3, and L4,\n             respectively, an example algorithm is:\n                L3 = .25 * (OSF*(2048-L1 -L2)\n                L4 = .75 * (OSF*(2048-L1 -L2)')
rmSwitchScrMarginFactor = MibScalar((1, 3, 6, 1, 4, 1, 9, 10, 10, 1, 1, 2), Integer32().subtype(subtypeSpec=ValueRangeConstraint(0, 100)).clone(1)).setMaxAccess("readwrite")
if mibBuilder.loadTexts: rmSwitchScrMarginFactor.setStatus('current')
if mibBuilder.loadTexts: rmSwitchScrMarginFactor.setDescription('The Sustained Cell Rate Margin Factor (SCRMF) is used in\n             Connection Admission Control (CAC) of VBR connections to\n             vary the weight given to the difference between Sustained\n             Cell Rate (scr) and Peak Cell Rate (pcr) specified in the\n             traffic contract. When calculating the equivalent bandwidth\n             offered by a connection, SCRMF is used as follows:\n                eqBw = scr + ((pcr - scr) * rcacVbrScrmf) / 100')
